152	/**
153	 * listUsers returns all auth users in a project.
154	 * @param project project identifier.
155	 * @param limit the total number of users to return.
156	 * @return an array of users info
157	 */
158	export async function listUsers(project: string, limit: number): Promise<UserInfo[]> {
159	  let queryLimit = limit;
160	  let offset = 0;
161	  if (limit > 500) {
162	    queryLimit = 500;
163	  }
164	  const userInfo: UserInfo[] = [];
165	  while (offset < limit) {
166	    if (queryLimit + offset > limit) {
167	      queryLimit = limit - offset;
168	    }
169	    const res = await apiClient.post<
170	      {
171	        limit: string;
172	        offset: string;
173	      },
174	      {
175	        recordsCount: string;
176	        userInfo: UserInfo[];
177	      }
178	    >(`/v1/projects/${project}/accounts:query`, {
179	      offset: offset.toString(),
180	      limit: queryLimit.toString(),
181	    });
182	    if (res.body.recordsCount === "0") {
183	      break;
184	    }
185	    offset += Number(res.body.recordsCount);
186	    const modifiedUserInfo = res.body.userInfo.map((ui) => {
187	      ui.uid = ui.localId;
188	      delete ui.localId;
189	      return ui;
190	    });
191	    userInfo.push(...modifiedUserInfo);
192	  }
193	  return userInfo;
194	}
