import { aiLogicOrigin } from "../api";
import { getErrStatus } from "../error";
import * as events from "../functions/events";

/** The API version used for AI Logic trigger management. */
const API_VERSION = "v1beta";

/** An exported HTTP client instance used to communicate with the AI Logic API. */
export const client = new Client({ urlPrefix: aiLogicOrigin(), apiVersion: API_VERSION, auth: true });

/** The minimal shape of an endpoint required to manage an AI Logic blocking trigger. */
export interface Endpoint {
  id: string;
  region: string;
  project: string;
  blockingTrigger: {
    eventType: string;
    options?: Record<string, unknown>;
  };
}

interface TriggerBody {
  cloudFunction: {
    id: string;
    locationId: string;
  };
}

/**
 * Returns the AI Logic trigger ID for a given blocking event type.
 * @param eventType the blocking trigger event type
 * @return the trigger ID used in AI Logic API calls
 */
function triggerId(eventType: string): string {
  switch (eventType) {
    case events.v2.AI_LOGIC_BEFORE_GENERATE_CONTENT:
      return "before-generate-content";
    case events.v2.AI_LOGIC_AFTER_GENERATE_CONTENT:
      return "after-generate-content";
    default:
      throw new Error(`Unexpected AI Logic blocking trigger event type ${eventType}`);
  }
}

/**
 * Returns the location segment for an endpoint's trigger. Global triggers (those
 * without the regionalWebhook option) use "global"; regional triggers use their region.
 * @param endpoint the AI Logic blocking endpoint
 * @return the location segment
 */
function triggerLocation(endpoint: Endpoint): string {
  return endpoint.blockingTrigger.options?.regionalWebhook ? endpoint.region : "global";
}

/**
 * Creates a new AI Logic blocking trigger via POST. If the POST fails with a 409
 * (conflict), falls back to PATCH to update the existing trigger. Any other POST
 * failure is re-thrown without calling PATCH.
 * @param endpoint the AI Logic blocking endpoint to create or update
 */
export async function upsertBlockingFunction(endpoint: Endpoint): Promise<void> {
  const id = triggerId(endpoint.blockingTrigger.eventType);
  const location = triggerLocation(endpoint);
  const body: TriggerBody = {
    cloudFunction: {
      id: endpoint.id,
      locationId: endpoint.region,
    },
  };

  try {
    await client.post<TriggerBody, unknown>(
      `projects/${endpoint.project}/locations/${location}/triggers`,
      body,
      { queryParams: { triggerId: id, validateOnly: "false" } },
    );
  } catch (err: unknown) {
    if (getErrStatus(err) !== 409) {
      throw err;
    }
    await client.patch<TriggerBody, unknown>(
      `projects/${endpoint.project}/locations/${location}/triggers/${id}`,
      body,
      { queryParams: { allowMissing: "false", validateOnly: "false" } },
    );
  }
}

/**
 * Deletes an AI Logic blocking trigger. Uses allowMissing so deletion is idempotent.
 * @param endpoint the AI Logic blocking endpoint to delete
 */
export async function deleteBlockingFunction(endpoint: Endpoint): Promise<void> {
  const id = triggerId(endpoint.blockingTrigger.eventType);
  const location = triggerLocation(endpoint);
  await client.delete<unknown>(
    `projects/${endpoint.project}/locations/${location}/triggers/${id}`,
    { queryParams: { allowMissing: "true", validateOnly: "false" } },
  );
}
