import { FirebaseError } from "../../../error";
import { Name, noop, Service } from "./index";

export class AILogicService implements Service {
  name: Name;
  api: string;

  constructor() {
    this.name = "ailogic";
    this.api = "firebasevertexai.googleapis.com";
    this.ensureTriggerRegion = noop;
  }

  ensureTriggerRegion: (ep: backend.Endpoint & backend.EventTriggered) => Promise<void>;

  /**
   * Ensure that at most one AI Logic blocking trigger of a given event type exists
   * per scope. Global triggers (no regionalWebhook option) allow at most one per event
   * type; regional triggers allow at most one per event type per region.
   * @param endpoint the AI Logic blocking endpoint
   * @param wantBackend the backend we are deploying
   */
  validateTrigger(endpoint: backend.Endpoint, wantBackend: backend.Backend): void {
    if (!backend.isBlockingTriggered(endpoint)) {
      return; // this should never happen
    }
    const eventType = endpoint.blockingTrigger.eventType;
    const isRegional = !!endpoint.blockingTrigger.options?.regionalWebhook;
    const blockingEndpoints = backend
      .allEndpoints(wantBackend)
      .filter((ep) => backend.isBlockingTriggered(ep)) as (backend.Endpoint &
      backend.BlockingTriggered)[];

    if (isRegional) {
      const conflict = blockingEndpoints.find(
        (ep) =>
          ep.blockingTrigger.eventType === eventType &&
          !!ep.blockingTrigger.options?.regionalWebhook &&
          ep.region === endpoint.region &&
          ep.id !== endpoint.id,
      );
      if (conflict) {
        throw new FirebaseError(
          `Can only create at most one regional AI Logic Trigger for ${eventType} in region ${endpoint.region}`,
        );
      }
    } else {
      const conflict = blockingEndpoints.find(
        (ep) =>
          ep.blockingTrigger.eventType === eventType &&
          !ep.blockingTrigger.options?.regionalWebhook &&
          ep.id !== endpoint.id,
      );
      if (conflict) {
        throw new FirebaseError(
          `Can only create at most one global AI Logic Trigger for ${eventType}`,
        );
      }
    }
  }

  /**
   * Registers the AI Logic blocking trigger with the AI Logic API.
   * @param ep the blocking endpoint
   */
  registerTrigger(ep: backend.Endpoint): Promise<void> {
    if (!backend.isBlockingTriggered(ep)) {
      return Promise.resolve(); // this should never happen
    }
    return ailogic.upsertBlockingFunction(ep);
  }

  /**
   * Un-registers the AI Logic blocking trigger from the AI Logic API.
   * @param ep the blocking endpoint
   */
  unregisterTrigger(ep: backend.Endpoint): Promise<void> {
    if (!backend.isBlockingTriggered(ep)) {
      return Promise.resolve(); // this should never happen
    }
    return ailogic.deleteBlockingFunction(ep);
  }
}
